import sys

def main():
    data = sys.stdin.buffer.read().split(b"\n")
    sums = {}
    get = sums.get
    for line in data[1:]:
        if not line:
            continue
        parts = line.rstrip(b"\r").split(b",")
        if len(parts) < 3:
            continue
        cat = parts[1]
        v = float(parts[2])
        sums[cat] = get(cat, 0.0) + v
    out = []
    for cat in sorted(sums):
        out.append(cat.decode() + "," + "%.2f" % sums[cat])
    if out:
        sys.stdout.write("\n".join(out) + "\n")

main()

import sys

def main():
    data = sys.stdin.buffer.read().split(b"\n")
    sums = {}
    get = sums.get
    for line in data[1:]:
        p = line.split(b",")
        if len(p) < 3:
            continue
        c = p[1]
        try:
            v = float(p[2])
        except ValueError:
            continue
        sums[c] = get(c, 0.0) + v
    out = [c.decode() + "," + "%.2f" % sums[c] for c in sorted(sums)]
    if out:
        sys.stdout.write("\n".join(out) + "\n")

main()

import sys
from collections import defaultdict

def main():
    data = sys.stdin.buffer.read().split(b"\n")
    sums = defaultdict(float)
    for line in data[1:]:
        p = line.split(b",")
        if len(p) < 3:
            continue
        try:
            sums[p[1]] += float(p[2])
        except ValueError:
            continue
    out = [c.decode() + "," + "%.2f" % sums[c] for c in sorted(sums)]
    if out:
        sys.stdout.write("\n".join(out) + "\n")

main()
